//! The file forms that are not the domain type (`[firewall]`, `[dhcp]` + `[tftp]`, `[ra]`)
//! round-trip exactly: domain value → file → domain value. Each one is tested with **every**
//! field away from its default — the fixture is generated by mutating each JSON leaf of a base
//! value, so a field added later is covered without touching these tests.

use serde::Serialize;
use serde::de::DeserializeOwned;
use serde_json::Value;

use super::ConfigFile;
use crate::api::SystemConfigExport;

/// Candidate replacements for a leaf: the first one the type accepts is kept.
fn candidates(leaf: &Value) -> Vec<Value> {
    match leaf {
        Value::Bool(b) => vec![Value::Bool(!b)],
        Value::Number(n) => {
            if let Some(u) = n.as_u64() {
                vec![(u + 1).into(), u.saturating_sub(1).into()]
            } else if let Some(i) = n.as_i64() {
                vec![(i + 1).into()]
            } else {
                vec![(n.as_f64().unwrap_or(0.0) + 0.5).into()]
            }
        }
        Value::String(s) => {
            let mut out = Vec::new();
            if let Ok(ip) = s.parse::<std::net::Ipv4Addr>() {
                let o = ip.octets();
                out.push(
                    std::net::Ipv4Addr::new(o[0], o[1], o[2], o[3] ^ 1)
                        .to_string()
                        .into(),
                );
            }
            if let Ok(ip) = s.parse::<std::net::Ipv6Addr>() {
                let mut seg = ip.segments();
                seg[7] ^= 1;
                out.push(std::net::Ipv6Addr::from(seg).to_string().into());
            }
            if let Ok(sa) = s.parse::<std::net::SocketAddr>() {
                out.push(
                    std::net::SocketAddr::new(sa.ip(), sa.port() ^ 1)
                        .to_string()
                        .into(),
                );
            }
            out.push(format!("{s}x").into());
            // URLs and other strings ending in a number (`udp://host:53`).
            if let Some(d) = s.chars().last().and_then(|c| c.to_digit(10)) {
                out.push(format!("{}{}", &s[..s.len() - 1], (d + 1) % 10).into());
            }
            out.push("mutated".into());
            // Human durations (RA lifetimes).
            out.push("infinity".into());
            out.push("2h".into());
            out
        }
        Value::Null => vec![
            "mutated".into(),
            7.into(),
            true.into(),
            "10.0.0.7".into(),
            "2001:db8::7".into(),
            "10.0.0.7:53".into(),
            "aa:bb:cc:dd:ee:07".into(),
        ],
        _ => Vec::new(),
    }
}

/// Leaves kept as in the base: moving them makes the fixture itself invalid, not lossy.
const FIXED: &[&str] = &[
    // Only static hosts are config; others are not exported at all.
    "/hosts/0/origin",
    // Must match the answer's type.
    "/dns_rewrites/0/rtype",
    // Import flag, not config.
    "/overwrite",
    // Pinned at `Infinity` in `base()`: the known loss is that value specifically.
    "/ra_prefixes/0/preferred_lifetime",
    "/ra_prefixes/0/valid_lifetime",
];

/// Variant names from serde's "unknown variant `x`, expected one of `A`, `B`" error.
fn enum_variants(err: &str) -> Vec<String> {
    let Some(rest) = err.split("expected ").nth(1) else {
        return Vec::new();
    };
    rest.split('`')
        .skip(1)
        .step_by(2)
        .map(str::to_string)
        .collect()
}

fn leaf_paths(v: &Value, prefix: &str, out: &mut Vec<String>) {
    match v {
        Value::Object(map) => {
            for (k, child) in map {
                leaf_paths(child, &format!("{prefix}/{k}"), out);
            }
        }
        // An empty list has no leaves to move: report it so `base()` gets an entry.
        Value::Array(items) if items.is_empty() => out.push(prefix.to_string()),
        Value::Array(items) => {
            for (i, child) in items.iter().enumerate() {
                leaf_paths(child, &format!("{prefix}/{i}"), out);
            }
        }
        _ => out.push(prefix.to_string()),
    }
}

/// Moves every leaf under `prefix` away from its value where the type allows it. Returns
/// the mutated value and the leaves no candidate fitted (to extend the base by hand).
fn mutate_all<T: Serialize + DeserializeOwned>(base: &T, prefix: &str) -> (T, Vec<String>) {
    let mut json = serde_json::to_value(base).unwrap();
    let mut paths = Vec::new();
    leaf_paths(&json[prefix.trim_start_matches('/')], prefix, &mut paths);
    let mut untouched = Vec::new();
    for path in paths {
        if FIXED.contains(&path.as_str()) {
            continue;
        }
        let original = json.pointer(&path).cloned().unwrap();
        let mut accepted = false;
        let mut cands = candidates(&original);
        let mut i = 0;
        while i < cands.len() {
            let cand = cands[i].clone();
            i += 1;
            *json.pointer_mut(&path).unwrap() = cand.clone();
            match serde_json::from_value::<T>(json.clone()) {
                Ok(t) if serde_json::to_value(&t).unwrap().pointer(&path) == Some(&cand) => {
                    accepted = true;
                    break;
                }
                Ok(_) => {}
                // A unit enum names its variants in the error: try the others.
                Err(e) if i == 1 => cands.extend(
                    enum_variants(&e.to_string())
                        .into_iter()
                        .filter(|v| Value::String(v.clone()) != original)
                        .map(Value::String),
                ),
                Err(_) => {}
            }
        }
        if !accepted {
            *json.pointer_mut(&path).unwrap() = original;
            untouched.push(path);
        }
    }
    (serde_json::from_value(json).unwrap(), untouched)
}

/// One entry in every list section, every optional section present: the starting point the
/// mutation moves away from.
